SELECT game_id AS "gameId", provider_id AS "providerId", sequence_id AS "sequenceId", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.provider_tick_sequences WHERE game_id = #{gameId}
AND provider_id = #{providerId}
AND sequence_id = #{sequenceId}
ORDER BY provider_id, sequence_id

